# ==========================================
# FEUILLE DE STYLE
# ==========================================

CSS = """
@import url('https://fonts.googleapis.com/css2?family=Rajdhani:wght@500;600;700&family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500;600&display=swap');

:root {
    --fond: #061326;
    --carte: rgba(11, 34, 57, 0.72);
    --bord: rgba(56, 189, 248, 0.28);
    --cyan: #22D3EE;
    --bleu: #3B82F6;
    --ambre: #F59E0B;
    --texte: #E6F1FB;
    --doux: #9CC3E0;
}

/* ----- Fond de l'application : courbes de niveau ----- */
.stApp {
    background-color: var(--fond) !important;
    background-image:
        url("data:image/svg+xml,__SVG__"),
        radial-gradient(1100px 620px at 92% -6%, rgba(34, 211, 238, 0.17), transparent 62%),
        radial-gradient(900px 700px at -6% 106%, rgba(59, 130, 246, 0.20), transparent 62%),
        radial-gradient(900px 400px at 55% 112%, rgba(99, 102, 241, 0.10), transparent 62%) !important;
    background-size: cover, auto, auto, auto !important;
    background-position: center, 0 0, 0 0, 0 0 !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
    font-family: 'IBM Plex Sans', 'Segoe UI', sans-serif !important;
    color: var(--texte);
}

header[data-testid="stHeader"] { background: transparent !important; }
[data-testid="stDecoration"], [data-testid="stStatusWidget"] { display: none; }
#MainMenu, footer { visibility: hidden; }

.block-container {
    padding-top: 2.2rem !important;
    max-width: 1400px;
    animation: apparition 0.5s ease-out;
}

@keyframes apparition {
    from { opacity: 0; transform: translateY(8px); }
    to { opacity: 1; transform: translateY(0); }
}

/* ----- Titres ----- */
h1, h2, h3, h4 {
    font-family: 'Rajdhani', 'Segoe UI', sans-serif !important;
    letter-spacing: 0.04em;
    color: var(--texte);
}

h1 {
    font-weight: 700 !important;
    text-transform: uppercase;
    background: linear-gradient(90deg, #FFFFFF 0%, #22D3EE 70%);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
}

h2, h3 {
    font-weight: 600 !important;
    border-left: 3px solid var(--cyan);
    padding-left: 12px !important;
    line-height: 1.2 !important;
}
h2 { font-size: 1.7rem !important; }
h3 { font-size: 1.35rem !important; }

p, label, li { color: var(--texte); }
[data-testid="stCaptionContainer"] { color: var(--doux) !important; }

/* ----- Barre latérale ----- */
[data-testid="stSidebar"] {
    background: linear-gradient(180deg, rgba(8, 28, 50, 0.97), rgba(5, 16, 32, 0.97)) !important;
    border-right: 1px solid var(--bord);
}
[data-testid="stSidebar"] * { color: var(--texte); }

[data-testid="stSidebar"] [role="radiogroup"] label {
    padding: 7px 10px;
    border-radius: 10px;
    border-left: 3px solid transparent;
    transition: background 0.15s, border-color 0.15s;
}
[data-testid="stSidebar"] [role="radiogroup"] label:hover {
    background: rgba(34, 211, 238, 0.08);
}
[data-testid="stSidebar"] [role="radiogroup"] label:has(input:checked) {
    background: linear-gradient(90deg, rgba(34, 211, 238, 0.22), rgba(34, 211, 238, 0.02));
    border-left-color: var(--cyan);
}

.logo { display: flex; align-items: center; gap: 12px; padding: 6px 0 4px 0; }
.logo-nom {
    font-family: 'Rajdhani', sans-serif;
    font-weight: 700; font-size: 1.7rem; letter-spacing: 0.12em; line-height: 1;
    color: #FFFFFF;
}
.logo-sous {
    font-size: 0.72rem; letter-spacing: 0.08em; text-transform: uppercase;
    color: var(--doux); margin: 2px 0 14px 0;
}

.statut {
    display: inline-block; padding: 6px 12px; border-radius: 999px;
    font-size: 0.78rem; font-weight: 500; border: 1px solid var(--bord);
    background: rgba(11, 34, 57, 0.8);
}
.statut.ok { border-color: rgba(52, 211, 153, 0.6); color: #6EE7B7; }
.statut.alerte { border-color: rgba(245, 158, 11, 0.6); color: #FCD34D; }
.statut.neutre { color: var(--doux); }

/* ----- En-tête de page ----- */
.hero {
    padding: 26px 30px; margin-bottom: 18px; border-radius: 18px;
    border: 1px solid var(--bord);
    background:
        linear-gradient(135deg, rgba(34, 211, 238, 0.14), rgba(59, 130, 246, 0.05) 55%, rgba(6, 19, 38, 0.6)),
        var(--carte);
    backdrop-filter: blur(6px);
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.35);
}
.hero-badge {
    display: inline-block; font-size: 0.72rem; letter-spacing: 0.18em; font-weight: 600;
    color: var(--cyan); border: 1px solid var(--bord); border-radius: 999px; padding: 3px 12px;
}
.hero-titre {
    font-family: 'Rajdhani', sans-serif; font-weight: 700; font-size: 3.4rem; line-height: 1.05;
    letter-spacing: 0.14em; margin: 10px 0 2px 0;
    background: linear-gradient(90deg, #FFFFFF 0%, #22D3EE 75%);
    -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
}
.hero-sous { color: var(--doux); font-size: 1.05rem; margin: 0 0 14px 0; }
.puce {
    display: inline-block; margin: 0 8px 6px 0; padding: 4px 12px; border-radius: 999px;
    font-size: 0.82rem; border: 1px solid var(--bord); background: rgba(6, 19, 38, 0.55);
}
.puce.ok { border-color: rgba(52, 211, 153, 0.6); color: #6EE7B7; }
.puce.alerte { border-color: rgba(245, 158, 11, 0.6); color: #FCD34D; }

/* ----- Cartes d'indicateurs ----- */
.kpi {
    display: flex; gap: 14px; align-items: center; padding: 16px 18px; border-radius: 16px;
    border: 1px solid var(--bord); border-left: 4px solid var(--cyan);
    background: var(--carte); backdrop-filter: blur(6px);
    box-shadow: 0 8px 28px rgba(0, 0, 0, 0.28);
    transition: transform 0.18s, box-shadow 0.18s; min-height: 132px;
}
.kpi:hover { transform: translateY(-3px); box-shadow: 0 14px 34px rgba(34, 211, 238, 0.12); }
.kpi.ambre { border-left-color: var(--ambre); }
.kpi.bleu { border-left-color: var(--bleu); }
.kpi-icone { font-size: 1.9rem; line-height: 1; }
.kpi-titre {
    font-size: 0.74rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--doux);
}
.kpi-valeur {
    font-family: 'IBM Plex Mono', monospace; font-weight: 600; font-size: 1.85rem; line-height: 1.15;
    color: #FFFFFF; white-space: nowrap;
}
.kpi-unite { font-size: 0.9rem; font-weight: 400; color: var(--doux); }
.kpi-detail { font-size: 0.78rem; color: var(--doux); margin-top: 2px; }

/* ----- Composants Streamlit ----- */
[data-testid="stMetric"] {
    background: var(--carte) !important;
    border: 1px solid var(--bord) !important;
    border-left: 4px solid var(--cyan) !important;
    border-radius: 14px; padding: 14px 16px !important;
    backdrop-filter: blur(6px);
}
[data-testid="stMetricLabel"] { color: var(--doux) !important; }
[data-testid="stMetricValue"] {
    font-family: 'IBM Plex Mono', monospace !important; color: #FFFFFF !important;
}

[data-testid="stAlert"] {
    border-radius: 12px; border: 1px solid var(--bord);
    background: rgba(11, 34, 57, 0.78); backdrop-filter: blur(6px);
}
[data-testid="stAlert"] p { color: var(--texte) !important; }

div.stButton > button, div.stDownloadButton > button {
    background: linear-gradient(135deg, #22D3EE, #3B82F6) !important;
    color: #04101F !important; font-weight: 600; border: none !important; border-radius: 10px;
    padding: 0.5rem 1.2rem; transition: transform 0.15s, box-shadow 0.15s;
}
div.stButton > button:hover, div.stDownloadButton > button:hover {
    transform: translateY(-2px); box-shadow: 0 8px 22px rgba(34, 211, 238, 0.35);
}

[data-testid="stDataFrame"] {
    border: 1px solid var(--bord); border-radius: 12px; overflow: hidden;
}
[data-testid="stExpander"] {
    border: 1px solid var(--bord) !important; border-radius: 12px;
    background: rgba(11, 34, 57, 0.55);
}
[data-testid="stPlotlyChart"] {
    border: 1px solid var(--bord); border-radius: 14px; padding: 6px;
    background: rgba(8, 24, 44, 0.55); backdrop-filter: blur(6px);
}
hr { border-color: var(--bord) !important; }

[data-baseweb="tab-list"] { gap: 6px; }
button[role="tab"] {
    font-family: 'Rajdhani', sans-serif !important; font-weight: 600 !important;
    font-size: 1.1rem !important; letter-spacing: 0.05em;
    border-radius: 10px 10px 0 0; padding: 8px 18px !important;
}
button[role="tab"][aria-selected="true"] { background: rgba(34, 211, 238, 0.10); color: #FFFFFF !important; }
[data-baseweb="tab-highlight"] { background-color: var(--cyan) !important; }

.usage {
    padding: 16px 18px; border-radius: 16px; border: 1px solid var(--bord);
    background: var(--carte); backdrop-filter: blur(6px); min-height: 150px;
    box-shadow: 0 8px 28px rgba(0, 0, 0, 0.25);
}
.usage-titre {
    font-family: 'Rajdhani', sans-serif; font-weight: 700; font-size: 1.25rem;
    letter-spacing: 0.06em; color: #FFFFFF; margin-bottom: 6px;
}
.usage-texte { font-size: 0.9rem; color: var(--doux); line-height: 1.45; }

::-webkit-scrollbar { width: 9px; height: 9px; }
::-webkit-scrollbar-thumb { background: rgba(56, 189, 248, 0.35); border-radius: 8px; }
::-webkit-scrollbar-track { background: transparent; }
"""


def _compacter(css):
    """Supprime indentation et lignes vides : évite que le Markdown les interprète."""
    return "\n".join(ligne.strip() for ligne in css.splitlines() if ligne.strip())


def appliquer_theme():
    """Injecte la feuille de style dans la page."""
    css = _compacter(CSS).replace("__SVG__", _SVG_ENCODE)
    st.markdown(f"<style>{css}</style>", unsafe_allow_html=True)


# ==========================================
# GRAPHIQUES
# ==========================================

def style_figure(fig):
    """Applique le style HYDROSTAT à une figure Plotly (fond transparent, grilles bleutées)."""
    try:
        fig.update_layout(
            template="plotly_dark",
            paper_bgcolor="rgba(0,0,0,0)",
            plot_bgcolor="rgba(8,24,44,0.35)",
            font=dict(
                family="IBM Plex Sans, Segoe UI, sans-serif",
                color="#CFE6F7",
                size=13
            ),
            colorway=COULEURS,
            margin=dict(l=44, r=22, t=52, b=42),
            hoverlabel=dict(
                bgcolor="#0B2239",
                bordercolor=CYAN,
                font=dict(color=TEXTE)
            ),
            legend=dict(bgcolor="rgba(0,0,0,0)"),
            title=dict(font=dict(family="Rajdhani, sans-serif", size=19, color=TEXTE))
        )

        axe = dict(
            gridcolor="rgba(56,189,248,0.10)",
            zerolinecolor="rgba(56,189,248,0.25)",
            linecolor="rgba(56,189,248,0.35)",
            tickfont=dict(color=TEXTE_DOUX),
            title=dict(font=dict(color=TEXTE_DOUX))
        )

        fig.update_xaxes(**axe)
        fig.update_yaxes(**axe)

    except (ValueError, KeyError, TypeError):
        pass    # un échec de style ne doit jamais empêcher d'afficher le graphique

    return fig


# ==========================================
# BLOCS HTML
# ==========================================

def nombre(valeur, decimales=0):
    """Nombre avec espace pour les milliers (1 560)."""
    return f"{valeur:,.{decimales}f}".replace(",", " ")


def _html(texte):
    """HTML sur une seule ligne : le Markdown ne doit pas l'interpréter."""
    return "".join(ligne.strip() for ligne in texte.splitlines())


def logo_sidebar():
    """Logo vague + nom + sous-titre de la barre latérale."""
    return _html("""
        <div class="logo">
        <svg width="38" height="38" viewBox="0 0 48 48" fill="none" stroke="#22D3EE"
             stroke-width="3" stroke-linecap="round" stroke-linejoin="round">
        <path d="M4 30c5-8 9-8 14 0s9 8 14 0 9-8 12-4"/>
        <path d="M4 40c5-8 9-8 14 0s9 8 14 0 9-8 12-4" opacity="0.55"/>
        <path d="M24 5c-4 6-7 9-7 13a7 7 0 0 0 14 0c0-4-3-7-7-13z"/>
        </svg>
        <div class="logo-nom">HYDROSTAT</div>
        </div>
        <div class="logo-sous">Hydrologie &amp; drainage pluvial</div>
    """)


def puce_statut(texte, etat="neutre"):
    """Pastille d'état (etat : ok, alerte ou neutre)."""
    return f'<span class="statut {etat}">● {html.escape(texte)}</span>'


def entete(titre, sous_titre, puces=(), badge="HYDROLOGIE · GÉNIE CIVIL"):
    """Grand bandeau de tête. puces : liste de tuples (texte, etat)."""
    puces_html = "".join(
        f'<span class="puce {etat}">{html.escape(texte)}</span>'
        for texte, etat in puces
    )

    return _html(f"""
        <div class="hero">
        <span class="hero-badge">{html.escape(badge)}</span>
        <div class="hero-titre">{html.escape(titre)}</div>
        <p class="hero-sous">{html.escape(sous_titre)}</p>
        <div>{puces_html}</div>
        </div>
    """)


def carte_kpi(icone, titre, valeur, unite="", detail="", accent=""):
    """Carte d'indicateur (accent : '', 'ambre' ou 'bleu')."""
    unite_html = f'<span class="kpi-unite"> {html.escape(unite)}</span>' if unite else ""
    detail_html = f'<div class="kpi-detail">{html.escape(detail)}</div>' if detail else ""

    return _html(f"""
        <div class="kpi {accent}">
        <div class="kpi-icone">{icone}</div>
        <div>
        <div class="kpi-titre">{html.escape(titre)}</div>
        <div class="kpi-valeur">{html.escape(str(valeur))}{unite_html}</div>
        {detail_html}
        </div>
        </div>
    """)


def carte_usage(icone, titre, texte):
    """Carte « à quoi servent les données » (icône, titre, courte explication)."""
    return _html(f"""
        <div class="usage">
        <div class="usage-titre">{icone} {html.escape(titre)}</div>
        <div class="usage-texte">{html.escape(texte)}</div>
        </div>
    """)
